DROP TABLE IF EXISTS tmp_a_hechos;
DROP TABLE IF EXISTS tmp_c_compras;
CREATE TABLE tmp_a_hechos WITH (format='PARQUET', parquet_compression='SNAPPY', external_location='s3://<bucket-maghsa-dwh>/analytics/runs/<run_id>/hechos_compras/', partitioned_by=ARRAY['anio','mes']) AS SELECT v.id_compra, replace(v.fecha,'-','') AS fecha_id, v.proveedor_id, v.producto_id, v.categoria_id, v.unidad_organizacional_id, CAST(v.cantidad AS double) AS cantidad, CAST(v.precio_unitario AS double) AS precio_unitario, round(CAST(v.cantidad AS double)*CAST(v.precio_unitario AS double),2) AS monto_total, v.moneda, v.condicion_pago, CAST(NULLIF(trim(v.lead_time_dias),'') AS integer) AS lead_time_dias, v.anio, v.mes FROM tmp_v_compras v JOIN (SELECT anio, mes, row_number() OVER (ORDER BY anio, mes) AS rk FROM (SELECT DISTINCT anio, mes FROM tmp_v_compras)) m ON v.anio = m.anio AND v.mes = m.mes WHERE m.rk BETWEEN 1 AND 100;
CREATE TABLE tmp_c_compras WITH (format='PARQUET', parquet_compression='SNAPPY', external_location='s3://<bucket-maghsa-dwh>/curated/runs/<run_id>/compras/', partitioned_by=ARRAY['anio','mes']) AS SELECT v.id_compra, v.fecha, v.proveedor_id, v.producto_id, v.categoria_id, v.unidad_organizacional_id, CAST(v.cantidad AS double) AS cantidad, CAST(v.precio_unitario AS double) AS precio_unitario, CAST(NULLIF(trim(v.lead_time_dias),'') AS integer) AS lead_time_dias, replace(v.fecha,'-','') AS fecha_id, round(CAST(v.cantidad AS double)*CAST(v.precio_unitario AS double),2) AS monto_total, v.anio, v.mes FROM tmp_v_compras v JOIN (SELECT anio, mes, row_number() OVER (ORDER BY anio, mes) AS rk FROM (SELECT DISTINCT anio, mes FROM tmp_v_compras)) m ON v.anio = m.anio AND v.mes = m.mes WHERE m.rk BETWEEN 1 AND 100;
